// A sound board for the developer machine: every sound effect of the game on its own button, so
// they can be listened to one by one without having to meet each thing in a run.
// Opened with ?sounds on localhost (see main.ts). It is not part of the game the players get.
import { Sfx } from './audio.ts';

export interface Sound {
  group: string;
  label: string;
  /** when in a run it is heard */
  when: string;
  play: (sfx: Sfx) => void;
}

/** play `fn` `times` times, `gap` milliseconds apart */
const repeat = (times: number, gap: number, fn: () => void): void => {
  for (let k = 0; k < times; k++) setTimeout(fn, k * gap);
};

