const CSS = `
.sb{position:fixed;inset:0;z-index:99999;overflow:auto;background:#0b1018;color:#e8eef7;
  font:15px/1.5 "Noto Sans TC","PingFang TC","Microsoft JhengHei",sans-serif;padding:20px 16px 48px}
.sb h1{font-size:22px;margin:0 0 4px}
.sb p{margin:0 0 16px;color:#9fb0c6;max-width:60ch}
.sb h2{font-size:15px;margin:22px 0 8px;color:#ffc21f;letter-spacing:.04em}
.sb .grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:8px}
.sb button{display:block;width:100%;text-align:left;padding:10px 12px;border-radius:10px;cursor:pointer;
  border:1px solid #2a3a50;background:#142033;color:inherit;font:inherit}
.sb button:hover{border-color:#2ee58a}
.sb button:active,.sb button.on{background:#1c3a2e;border-color:#2ee58a}
.sb button b{display:block;font-size:16px}
.sb button span{display:block;font-size:12.5px;color:#9fb0c6}
.sb .bar{display:flex;gap:8px;flex-wrap:wrap;margin:0 0 6px}
.sb .bar button{width:auto;text-align:center;font-weight:700}
`;

/** Show the board over the page. Returns the element, so it can be taken away again. */
export function openSoundboard(sfx: Sfx = new Sfx()): HTMLElement {
  sfx.muted = false;
  const root = document.createElement('div');
  root.className = 'sb';
  const style = document.createElement('style');
  style.textContent = CSS;
  root.append(style);

  const h1 = document.createElement('h1');
  h1.textContent = 'K 線衝浪 音效試聽';
  const intro = document.createElement('p');
  intro.textContent =
    '每一顆按鈕是遊戲裡的一個音效，下面那行字是它在什麼時候出現。音效都是程式合成的，沒有人聲。這一頁只在開發用的電腦上打得開。';
  root.append(h1, intro);

  const bar = document.createElement('div');
  bar.className = 'bar';
  const all = document.createElement('button');
  all.textContent = '全部依序播一次';
  all.addEventListener('click', () => {
    sfx.unlock();
    SOUNDS.forEach((sound, k) => {
      setTimeout(() => {
        sound.play(sfx);
        for (const b of root.querySelectorAll('button.on')) b.classList.remove('on');
        root.querySelector(`[data-k="${k}"]`)?.classList.add('on');
      }, k * 1300);
    });
  });
  const back = document.createElement('button');
  back.textContent = '回到遊戲';
  back.addEventListener('click', () => root.remove());
  bar.append(all, back);
  root.append(bar);

  let grid: HTMLElement | null = null;
  let group = '';
  SOUNDS.forEach((sound, k) => {
    if (sound.group !== group) {
      group = sound.group;
      const h2 = document.createElement('h2');
      h2.textContent = group;
      grid = document.createElement('div');
      grid.className = 'grid';
      root.append(h2, grid);
    }
    const button = document.createElement('button');
    button.dataset.k = String(k);
    const name = document.createElement('b');
    name.textContent = sound.label;
    const when = document.createElement('span');
    when.textContent = sound.when;
    button.append(name, when);
    button.addEventListener('click', () => {
      // (browsers only let a page make sound after a click: this is one)
      sfx.unlock();
      sound.play(sfx);
    });
    grid?.append(button);
  });
  document.body.append(root);
  return root;
}
